<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class SupportTicket extends Model{protected $fillable=['user_id','assigned_to','category','subject','priority','status','resolved_at'];protected function casts():array{return ['resolved_at'=>'datetime'];}public function user(){return $this->belongsTo(User::class);}public function assignee(){return $this->belongsTo(User::class,'assigned_to');}public function messages(){return $this->hasMany(SupportMessage::class,'ticket_id');}}